\begin{proposition}
\label{prop:8-8}




\dcref{ch8:8.8}
Let $M$ be a smooth manifold, possibly with boundary.
\begin{enumerate}
\item If $X,Y\in\mathfrak{X}(M)$ and $f,g\in C^\infty(M)$, then
$fX+gY$ is smooth.
\item Consequently, $\mathfrak{X}(M)$ is a module over $C^\infty(M)$.
\end{enumerate}
\end{proposition}

